create table idempotency_record (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, operation_scope varchar(128) not null, signature varchar(128) not null, idempotency_key varchar(255) not null, resource_id varchar(255), primary key (operation_scope, idempotency_key));
create table keel_timer (attempts integer not null, claimed_until timestamp(6) with time zone, due_at timestamp(6) with time zone not null, parked_at timestamp(6) with time zone, claim_token uuid, entity_id uuid not null, id uuid not null, spec varchar(120), kind varchar(160) not null, primary key (id), constraint uq_keel_timer_kind_entity unique (kind, entity_id));
create table order_lines (quantity integer not null, unit_price numeric(19,3) not null, id uuid not null, order_id uuid, product_id uuid not null, sku varchar(64) not null, product_name varchar(200) not null, primary key (id));
create table orders (line_count integer, total_amount numeric(19,3), action_required_since timestamp(6) with time zone, cancel_order_payment_awaiting_since timestamp(6) with time zone, capture_order_payment_awaiting_since timestamp(6) with time zone, charge_order_awaiting_since timestamp(6) with time zone, created_at timestamp(6) with time zone, lock_version bigint not null, updated_at timestamp(6) with time zone, id uuid not null, payment_id uuid, customer_ref varchar(200) not null, customer_email varchar(254) not null, currency varchar(255) not null, customer_action text, failure_reason varchar(255) check ((failure_reason in ('DECLINED','INSUFFICIENT_FUNDS','EXPIRED_CARD','AUTHENTICATION_FAILED','FRAUD_SUSPECTED','INVALID_PAYMENT_METHOD','NOT_RECEIVED','PROCESSING_ERROR'))), status varchar(255) check ((status in ('PENDING_PAYMENT','ACTION_REQUIRED','AUTHORIZED','PAID','CANCELING','CANCELED','PAYMENT_FAILED'))), primary key (id));
create table outbox_event (attempts integer not null, created_at timestamp(6) with time zone not null, next_attempt_at timestamp(6) with time zone, published_at timestamp(6) with time zone, id uuid not null, last_error varchar(1024), destination varchar(255) not null, event_type varchar(255) not null, payload text not null, routing_key varchar(255) not null, primary key (id));
create table processed_event (processed_at timestamp(6) with time zone not null, handler_id varchar(128) not null, event_id varchar(255) not null, primary key (handler_id, event_id));
create table products (price numeric(19,3), retired boolean, lock_version bigint not null, source_version bigint not null, id uuid not null, sku varchar(64), name varchar(200), currency varchar(255), constraint uk_products_natural primary key (id));
create table reconciliation_claim (claimed_at timestamp(6) with time zone not null, entity_id uuid not null, activation varchar(120) not null, primary key (entity_id, activation));
create index ix_idempotency_record_expires_at on idempotency_record (expires_at);
create index ix_keel_timer_due_at on keel_timer (due_at);
create index ix_order_lines_order_id on order_lines (order_id);
create index idx_orders_customer_ref_created_at on orders (customer_ref, created_at);
create index idx_orders_status_charge_order_awaiting_since on orders (status, charge_order_awaiting_since);
create index idx_orders_status_capture_order_payment_awaiting_since on orders (status, capture_order_payment_awaiting_since);
create index idx_orders_status_cancel_order_payment_awaiting_since on orders (status, cancel_order_payment_awaiting_since);
create index idx_orders_status_action_required_since on orders (status, action_required_since);
create index ix_outbox_event_pending on outbox_event (published_at, created_at);
create index ix_processed_event_processed_at on processed_event (processed_at);
create index ix_reconciliation_claim_claimed_at on reconciliation_claim (claimed_at);
alter table if exists order_lines add constraint fk_order_lines_order foreign key (order_id) references orders;
